INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('a9c41392-165e-46fb-96e4-a9c2ea7ae8f3'::uuid, 'card_description', 'Corick, from the Irish for ''confluence'', keeps a stone circle and a stone row, often believed aligned for a greater purpose, yet too crude to have been advanced astronomical calculators.', 'A megalithic stone circle and alignment in a boggy townland. The circle and row form a single planned complex dating to around the 4th–1st millennium BC.', 'teaser-card-s025-rollback:a9c41392-165e-46fb-96e4-a9c2ea7ae8f3:card_description', 'rollback of teaser-card-s025: card_description ''A megalithic stone circle and alignment in a boggy townland. The circle and row form a single planned complex dating to around the 4th–1st millennium BC.'' restored on Corick', '03adaa40cbd4caf907ca0a5e39ea46c0ee3d2ef948a394ba3e3097357df8b24b|e3fcaaa1a93e01339e01da27de57e5917ba44cac1954a712384e9fdda3f42ece|e3fcaaa1a93e01339e01da27de57e5917ba44cac1954a712384e9fdda3f42ece', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Corick, from the Irish for ''confluence'', keeps a stone circle and a stone row, often believed aligned for a greater purpose, yet too crude to have been advanced astronomical calculators."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the name Corick comes from the Irish for ''confluence'' [S1]; Corick has a stone circle [S2]; Corick has a stone row [S2]; the stones are often believed to have been aligned for a greater purpose [S4]; the stones are too crude to have been used as advanced astronomical calculators [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Corick is a megalithic site. [SUPPORTED: https://en.wikipedia.org/wiki/Corick]; It is in Northern Ireland. [SUPPORTED: https://en.wikipedia.org/wiki/Corick]; The name Corick comes from the Irish for ''confluence''. [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Corick]; It includes a stone circle and a stone row. [SUPPORTED: https://en.wikipedia.org/wiki/Corick]; The monuments are often believed to be aligned for a greater purpose. [SUPPORTED: https://en.wikipedia.org/wiki/Corick]; The stones are too crude to have been advanced astronomical calculators. [SUPPORTED: https://en.wikipedia.org/wiki/Corick]"}]'::jsonb),
    ('aae646d9-5b3a-4a7c-9754-6d5ce4a0a9de'::uuid, 'card_description', 'On the southern slope of the Turrialba Volcano lie the 43 stone foundations, aqueducts and roadways of Guayabo National Monument, abandoned in 1400 CE for reasons that remain a mystery.', 'A pre-Columbian city occupied from 1000 BC to 1400 AD with stone-paved roads and aqueducts that still carry water today. Only a fraction of the site has been excavated.', 'teaser-card-s025-rollback:aae646d9-5b3a-4a7c-9754-6d5ce4a0a9de:card_description', 'rollback of teaser-card-s025: card_description ''A pre-Columbian city occupied from 1000 BC to 1400 AD with stone-paved roads and aqueducts that still carry water today. Only a fraction of the site has been excavated.'' restored on Guayabo National Monument', '12ae63279bc47b99cca852354d2bb965e844cb86c652fbbd427453ff63fdc89a|503d6019de75659e4aee2b80b8eddbefa043792c3675add2061e8633aeda2a0a|503d6019de75659e4aee2b80b8eddbefa043792c3675add2061e8633aeda2a0a', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the southern slope of the Turrialba Volcano lie the 43 stone foundations, aqueducts and roadways of Guayabo National Monument, abandoned in 1400 CE for reasons that remain a mystery."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site lies on the southern slope of the Turrialba Volcano [S2]; the site has 43 stone foundations [S6]; the site has aqueducts [S6]; the site has roadways [S6]; the site was abandoned in 1400 CE [S4]; the reasons for the abandonment remain a mystery [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Guayabo National Monument is an archaeological site (a pre-Columbian settlement) in Costa Rica [SUPPORTED: https://en.wikipedia.org/wiki/Guayabo_National_Monument]; It lies on the southern slope of the Turrialba Volcano [SUPPORTED: https://en.wikipedia.org/wiki/Guayabo_National_Monument]; The known site has 43 stone foundations [SUPPORTED: https://en.wikipedia.org/wiki/Guayabo_National_Monument]; The known site has aqueducts [SUPPORTED: https://en.wikipedia.org/wiki/Guayabo_National_Monument]; The known site has roadways [SUPPORTED: https://en.wikipedia.org/wiki/Guayabo_National_Monument]; The site was abandoned in 1400 CE [SUPPORTED: https://en.wikipedia.org/wiki/Guayabo_National_Monument]; The reasons for the abandonment remain a mystery [SUPPORTED: https://en.wikipedia.org/wiki/Guayabo_National_Monument]"}]'::jsonb),
    ('ab336181-36c6-4505-b52b-181bed507d50'::uuid, 'card_description', 'Rione Terra began as a fortress of Greek colonists from Samos and keeps a Roman temple turned cathedral. In 1970 a sudden bradyseism raised its hill 1.7 m and the quarter was evacuated.', 'The original Greek acropolis of Dicearkia, later the Roman port city of Puteoli, built in the 6th century BC. It sits on an active volcanic field.', 'teaser-card-s025-rollback:ab336181-36c6-4505-b52b-181bed507d50:card_description', 'rollback of teaser-card-s025: card_description ''The original Greek acropolis of Dicearkia, later the Roman port city of Puteoli, built in the 6th century BC. It sits on an active volcanic field.'' restored on Rione Terra', '7ad9de7fc4fa0af898e4cd326c549db4257b1a6f2d2ddde03eebafb8f317aa58|b0886b9ec5477b7883e67c524007227b1c05eea893f7c90c55f4759e691cea84|b0886b9ec5477b7883e67c524007227b1c05eea893f7c90c55f4759e691cea84', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Rione Terra began as a fortress of Greek colonists from Samos and keeps a Roman temple turned cathedral. In 1970 a sudden bradyseism raised its hill 1.7 m and the quarter was evacuated."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Rione Terra began as a fortress [S2]; the fortress belonged to a settlement of Greek colonists from Samos [S2]; Rione Terra has a Roman temple [S4]; the Roman temple was converted into a cathedral that still stands [S5]; in 1970 a sudden bradyseism event occurred [S6]; the bradyseism raised the quarter''s hill by 1.7 m [S6]; the quarter was evacuated because of it [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Rione Terra is a historic quarter (ancient fortress) in Pozzuoli, Italy [SUPPORTED: https://en.wikipedia.org/wiki/Rione_Terra]; It began as a fortress [SUPPORTED: https://en.wikipedia.org/wiki/Rione_Terra]; The founders were Greek colonists from Samos [SUPPORTED: https://en.wikipedia.org/wiki/Rione_Terra]; It keeps a Roman temple [SUPPORTED: https://en.wikipedia.org/wiki/Rione_Terra]; The Roman temple was turned into the cathedral [SUPPORTED: https://en.wikipedia.org/wiki/Rione_Terra]; In 1970 a sudden bradyseism event occurred [SUPPORTED: https://en.wikipedia.org/wiki/Rione_Terra]; It raised the hill by 1.7 m [SUPPORTED: https://en.wikipedia.org/wiki/Rione_Terra]; The quarter was evacuated in 1970 [SUPPORTED: https://en.wikipedia.org/wiki/Rione_Terra]"}]'::jsonb),
    ('ac202ead-509d-4093-9680-2a4f4e74e8ea'::uuid, 'card_description', 'The Museum of Mosaics in Devnya stands over the House of Antiope, a Late Roman villa whose floor mosaics of Zeus, Ganymede and the gorgon Medusa are wholly pagan despite Christianity''s rise.', 'A museum built directly on top of a ruined Roman villa, displaying mosaics from the ancient city of Marcianopolis. The polychrome floors depict mythological scenes in vivid detail.', 'teaser-card-s025-rollback:ac202ead-509d-4093-9680-2a4f4e74e8ea:card_description', 'rollback of teaser-card-s025: card_description ''A museum built directly on top of a ruined Roman villa, displaying mosaics from the ancient city of Marcianopolis. The polychrome floors depict mythological scenes in vivid detail.'' restored on Museum of Mosaics, Devnya', '482f01bf67d09cd1096f09f386ba408ba8c746ccdf81a3b094d67aae2d2d1a40|92b9a32dc7e674737c18c1e372afcff87afcd951acaebb603cda91fe3d7c99e9|92b9a32dc7e674737c18c1e372afcff87afcd951acaebb603cda91fe3d7c99e9', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Museum of Mosaics in Devnya stands over the House of Antiope, a Late Roman villa whose floor mosaics of Zeus, Ganymede and the gorgon Medusa are wholly pagan despite Christianity''s rise."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Museum of Mosaics is in Devnya [S1]; the museum stands over the House of Antiope [S2, S3]; the House of Antiope is a Late Roman villa [S3]; the villa has floor mosaics [S3]; the mosaics depict Zeus, Ganymede and the gorgon Medusa [S7]; the mosaics are wholly pagan despite the rise of Christianity [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Museum of Mosaics stands in Devnya, Bulgaria, built over a ruined Roman villa [SUPPORTED: https://en.wikipedia.org/wiki/Museum_of_Mosaics,_Devnya]; The villa is the House of Antiope [SUPPORTED: https://en.wikipedia.org/wiki/Museum_of_Mosaics,_Devnya]; The villa is Late Roman [SUPPORTED: https://en.wikipedia.org/wiki/Museum_of_Mosaics,_Devnya]; The floor mosaics depict Zeus [SUPPORTED: https://en.wikipedia.org/wiki/Museum_of_Mosaics,_Devnya]; The floor mosaics depict Ganymede [SUPPORTED: https://en.wikipedia.org/wiki/Museum_of_Mosaics,_Devnya]; The floor mosaics depict the gorgon Medusa [SUPPORTED: https://en.wikipedia.org/wiki/Museum_of_Mosaics,_Devnya]; The mosaics are wholly (exclusively) pagan [SUPPORTED: https://en.wikipedia.org/wiki/Museum_of_Mosaics,_Devnya]; This is despite the rise of Christianity [SUPPORTED: https://en.wikipedia.org/wiki/Museum_of_Mosaics,_Devnya]"}]'::jsonb),
    ('ac2ef60c-347b-491c-a31b-39204e932a94'::uuid, 'card_description', 'Under Derby''s Duffield Road lay Strutt''s Park Roman Fort, built around the year 50, probably to protect a crossing of the Derwent. Digs in 1995 revealed terracing and a cobbled pavement.', 'Excavations in 1995 revealed terracing, stone wall footing and a cobbled pavement.', 'teaser-card-s025-rollback:ac2ef60c-347b-491c-a31b-39204e932a94:card_description', 'rollback of teaser-card-s025: card_description ''Excavations in 1995 revealed terracing, stone wall footing and a cobbled pavement.'' restored on Strutt''s Park Roman Fort', '68057029e06c54ef8f6cc1df0c0bb2a209dbcd34960c2079b05e3d04f06f5bda|ccca6e345bb3c19da471f53ff9dca997552b13bfc592e8afb2fc513e554adc8f|ccca6e345bb3c19da471f53ff9dca997552b13bfc592e8afb2fc513e554adc8f', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Under Derby''s Duffield Road lay Strutt''s Park Roman Fort, built around the year 50, probably to protect a crossing of the Derwent. Digs in 1995 revealed terracing and a cobbled pavement."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the fort lay under Duffield Road [S3]; Duffield Road is in Derby [S1, S3]; the fort was built around the year 50 [S2]; the fort was probably meant to protect a crossing of the Derwent [S6]; excavations in 1995 revealed terracing [S4]; excavations in 1995 revealed a cobbled pavement [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Strutt''s Park Roman Fort was a Roman fort in Derby, England [SUPPORTED: https://en.wikipedia.org/wiki/Strutt%27s_Park_Roman_Fort]; It lay under Duffield Road [SUPPORTED: https://en.wikipedia.org/wiki/Strutt%27s_Park_Roman_Fort]; It was built around the year 50 [SUPPORTED: https://en.wikipedia.org/wiki/Strutt%27s_Park_Roman_Fort]; Its purpose was probably to protect a crossing of the Derwent [SUPPORTED: https://en.wikipedia.org/wiki/Strutt%27s_Park_Roman_Fort]; Excavations in 1995 took place [SUPPORTED: https://en.wikipedia.org/wiki/Strutt%27s_Park_Roman_Fort]; They revealed terracing [SUPPORTED: https://en.wikipedia.org/wiki/Strutt%27s_Park_Roman_Fort]; They revealed a cobbled pavement [SUPPORTED: https://en.wikipedia.org/wiki/Strutt%27s_Park_Roman_Fort]"}]'::jsonb),
    ('ad61addd-d62b-4c88-972c-18ebf465a900'::uuid, 'card_description', 'A ditch and ramparts ringed Becan, a Maya ceremonial center in Campeche where trade goods from Teotihuacan were found. Occupied about 550 BCE, it was probably abandoned by about 1200.', 'Pre-Classic Maya city founded by 550 BC with a surrounding ditch and earthwork ramparts. Temple structures in the distinctive Rio Bec architectural style rise across the site.', 'teaser-card-s025-rollback:ad61addd-d62b-4c88-972c-18ebf465a900:card_description', 'rollback of teaser-card-s025: card_description ''Pre-Classic Maya city founded by 550 BC with a surrounding ditch and earthwork ramparts. Temple structures in the distinctive Rio Bec architectural style rise across the site.'' restored on Becan', 'ec704b800a5db367957e0a8b6b217ed522b639b9df3b908cda63af440acb1bc7|17aeb2de60f1325f5afee3e1a61546c0d4d9726dc3ae4fa897affeca9929bc2b|17aeb2de60f1325f5afee3e1a61546c0d4d9726dc3ae4fa897affeca9929bc2b', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "A ditch and ramparts ringed Becan, a Maya ceremonial center in Campeche where trade goods from Teotihuacan were found. Occupied about 550 BCE, it was probably abandoned by about 1200."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "a ditch and ramparts surrounded Becan [S5]; Becan is a Maya site [S1]; Becan was a ceremonial center [S3]; Becan is in Campeche [S2]; trade goods from Teotihuacan were found there [S4]; Becan was occupied about 550 BCE [S3]; Becan was probably abandoned by about 1200 [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Becan is a Maya archaeological site in the state of Campeche, Mexico [SUPPORTED: https://en.wikipedia.org/wiki/Becan]; Becan was a ceremonial center [SUPPORTED: https://en.wikipedia.org/wiki/Becan]; Trade goods from Teotihuacan were found there [SUPPORTED: https://en.wikipedia.org/wiki/Becan]; A ditch and ramparts ringed the site [SUPPORTED: https://en.wikipedia.org/wiki/Becan]; It was occupied about 550 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Becan]; It was probably abandoned by about 1200 [SUPPORTED: https://en.wikipedia.org/wiki/Becan]; The site belongs to the Maya civilization [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Becan]"}]'::jsonb),
    ('add7a025-751a-4335-98f4-8808ccc1221f'::uuid, 'card_description', 'From the air, cropmarks at Brandon Camp hinted at a Roman granary, and excavation confirmed it: a Roman fort, it seems, raised on a captured British fort on Brandon Hill.', 'Iron Age hill fort later reused as a Roman fort, with a roughly triangular enclosure 250 by 260 metres in Herefordshire. Two eras of occupation share the same defended hill.', 'teaser-card-s025-rollback:add7a025-751a-4335-98f4-8808ccc1221f:card_description', 'rollback of teaser-card-s025: card_description ''Iron Age hill fort later reused as a Roman fort, with a roughly triangular enclosure 250 by 260 metres in Herefordshire. Two eras of occupation share the same defended hill.'' restored on Brandon Camp', '343ad4212ccd6c1ebb9f7dca519ca6ead05e7e23373d61e21940c35db572915a|dce06f206de87c1eee88f6b62b59178573cd44560cc7ddb7f36a3936eca7f7b4|dce06f206de87c1eee88f6b62b59178573cd44560cc7ddb7f36a3936eca7f7b4', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "From the air, cropmarks at Brandon Camp hinted at a Roman granary, and excavation confirmed it: a Roman fort, it seems, raised on a captured British fort on Brandon Hill."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "aerial photographs showed cropmarks at Brandon Camp [S4]; the cropmarks were thought to indicate a Roman granary [S4]; excavation confirmed the granary [S6, S7]; it seems a Roman fort was built on a captured British fort [S5]; the site is on Brandon Hill [S2, S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Brandon Camp is an Iron Age hillfort that became a Roman fort, on Brandon Hill (Herefordshire, England) [SUPPORTED: https://en.wikipedia.org/wiki/Brandon_Camp]; Cropmarks seen from the air hinted at a Roman granary [SUPPORTED: https://en.wikipedia.org/wiki/Brandon_Camp]; Excavation confirmed the granary [SUPPORTED: https://en.wikipedia.org/wiki/Brandon_Camp]; The Roman fort seems to have been built on a captured British fort [SUPPORTED: https://en.wikipedia.org/wiki/Brandon_Camp]; The site lies on Brandon Hill [SUPPORTED: https://en.wikipedia.org/wiki/Brandon_Camp]"}]'::jsonb),
    ('ae6974c3-4079-4ce3-a3a4-70e4984ea2d4'::uuid, 'card_description', 'Finnestorp gave up more than 700 finds of weapons, horse gear and horses, some bridles and sword belts laid intact in pits. It is interpreted as a cult site where war booty was sacrificed.', 'A cult site where war booty was ritually destroyed and thrown into water from 350–550 AD. Over 700 artifacts include weapons deliberately chopped into pieces.', 'teaser-card-s025-rollback:ae6974c3-4079-4ce3-a3a4-70e4984ea2d4:card_description', 'rollback of teaser-card-s025: card_description ''A cult site where war booty was ritually destroyed and thrown into water from 350–550 AD. Over 700 artifacts include weapons deliberately chopped into pieces.'' restored on Finnestorp', '01befa28c7c05ef1a885141638653b84c2741a16eb7e443750131388556eb813|b4bbc5b7b5100fd222d72ba2a8259ebf139d1b1acae39f2c4fedb6fa9b749cc5|b4bbc5b7b5100fd222d72ba2a8259ebf139d1b1acae39f2c4fedb6fa9b749cc5', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Finnestorp gave up more than 700 finds of weapons, horse gear and horses, some bridles and sword belts laid intact in pits. It is interpreted as a cult site where war booty was sacrificed."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Finnestorp yielded more than 700 finds [S3]; the finds include weapons, horse gear and horses [S3]; some finds are bridles and sword belts laid intact in pits [S6]; Finnestorp is interpreted as a cult site where war booty was sacrificed [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Finnestorp is an archaeological site in Sweden [SUPPORTED: https://en.wikipedia.org/wiki/Finnestorp]; It is interpreted as a cult site [SUPPORTED: https://en.wikipedia.org/wiki/Finnestorp]; War booty was sacrificed there [SUPPORTED: https://en.wikipedia.org/wiki/Finnestorp]; More than 700 finds [SUPPORTED: https://en.wikipedia.org/wiki/Finnestorp]; The finds include weapons, horse gear and horses [SUPPORTED: https://en.wikipedia.org/wiki/Finnestorp]; Some bridles and sword belts were laid intact in pits [SUPPORTED: https://en.wikipedia.org/wiki/Finnestorp]"}]'::jsonb),
    ('af071bf2-f99f-4bf3-84d6-67093c74e5dd'::uuid, 'card_description', 'On a triangle of land projecting into a mere, Oakmere Hill Fort raised ramparts behind a ditch 50 ft wide at its zenith, one of only seven Iron Age hill forts in Cheshire.', 'Iron Age hill fort in Cheshire -- one of only seven in the county and unusually low-lying for its type. Scheduled as an Ancient Monument in a region where hill forts are exceptionally rare.', 'teaser-card-s025-rollback:af071bf2-f99f-4bf3-84d6-67093c74e5dd:card_description', 'rollback of teaser-card-s025: card_description ''Iron Age hill fort in Cheshire -- one of only seven in the county and unusually low-lying for its type. Scheduled as an Ancient Monument in a region where hill forts are exceptionally rare.'' restored on Oakmere Hill Fort', 'bc37dbc15f6c5b696f31b27670cda4637c69ea76f3460c992f7e6096085bcb7b|b2dd351d2ec0298a0cb22a52f9c5ddc75fdaecfb4541869d044b22a8faac1054|b2dd351d2ec0298a0cb22a52f9c5ddc75fdaecfb4541869d044b22a8faac1054', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a triangle of land projecting into a mere, Oakmere Hill Fort raised ramparts behind a ditch 50 ft wide at its zenith, one of only seven Iron Age hill forts in Cheshire."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the fort is on a triangle of land projecting into a mere [S2]; the fort has ramparts [S4]; a ditch lies in front of the ramparts [S4]; the ditch was 50 ft wide at its zenith [S5]; it is an Iron Age hill fort [S1]; it is one of only seven Iron Age hill forts in Cheshire [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Oakmere Hill Fort is a hill fort (a fortified settlement) [SUPPORTED: https://en.wikipedia.org/wiki/Oakmere_hill_fort]; It dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Oakmere_hill_fort]; It is in Cheshire and one of only seven hill forts there [SUPPORTED: https://en.wikipedia.org/wiki/Oakmere_hill_fort]; It sits on a triangular area of land [SUPPORTED: https://en.wikipedia.org/wiki/Oakmere_hill_fort]; The triangle of land projects into a mere [SUPPORTED: https://en.wikipedia.org/wiki/Oakmere_hill_fort]; Ramparts were raised with a ditch in front of them [SUPPORTED: https://en.wikipedia.org/wiki/Oakmere_hill_fort]; The ditch was 50 ft wide at its zenith [SUPPORTED: https://en.wikipedia.org/wiki/Oakmere_hill_fort]"}]'::jsonb),
    ('afa52222-ee6e-4b90-aae8-3078dae3ae71'::uuid, 'card_description', 'A magnetometry survey in 1997 found two entrances and signs of a thriving Iron Age settlement at Norsebury Ring, a Hampshire hillfort where Bronze Age and Roman pottery has also been found.', 'Ploughed almost to nothing on its south and east sides, this univallate hillfort survives only within a small copse. Double banks and ditches there remain hidden under trees and undergrowth.', 'teaser-card-s025-rollback:afa52222-ee6e-4b90-aae8-3078dae3ae71:card_description', 'rollback of teaser-card-s025: card_description ''Ploughed almost to nothing on its south and east sides, this univallate hillfort survives only within a small copse. Double banks and ditches there remain hidden under trees and undergrowth.'' restored on Norsebury Ring', 'a6c2eca5e391119980a2141a723d023f137d98b17c13d270b6f5ce8bba7fd1c5|934118934db7afa66908a75bdba97bc1a87f41b645872f4816565ba776566bf8|934118934db7afa66908a75bdba97bc1a87f41b645872f4816565ba776566bf8', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "A magnetometry survey in 1997 found two entrances and signs of a thriving Iron Age settlement at Norsebury Ring, a Hampshire hillfort where Bronze Age and Roman pottery has also been found."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "a magnetometry survey took place in 1997 [S2]; the survey found two entrances [S2]; the survey found signs of a thriving Iron Age settlement [S2]; Norsebury Ring is a hillfort in Hampshire [S1]; Bronze Age pottery has been found there [S3]; Roman pottery has been found there [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Norsebury Ring is a hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Norsebury_Ring]; It is in Hampshire [SUPPORTED: https://en.wikipedia.org/wiki/Norsebury_Ring]; A magnetometry survey was made in 1997 [SUPPORTED: https://en.wikipedia.org/wiki/Norsebury_Ring]; The survey found two entrances [SUPPORTED: https://en.wikipedia.org/wiki/Norsebury_Ring]; Signs of a thriving Iron Age settlement were found [SUPPORTED: https://en.wikipedia.org/wiki/Norsebury_Ring]; Bronze Age pottery has been found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Norsebury_Ring]; Roman pottery has been found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Norsebury_Ring]"}]'::jsonb),
    ('b074592e-44fe-4a6d-9bca-f8b7bd13ee69'::uuid, 'card_description', 'Two huge statues of Amenhotep III, the Colossi of Memnon have stood since 1350 BC. Of their 107 Roman-era inscriptions, many name Memnon, the mythical king one was wrongly thought to be.', 'The Colossi of Memnon are two large stone statues of the Pharaoh Amenhotep III, which stand at the front of the ruined Mortuary Temple of Amenhotep III.', 'teaser-card-s025-rollback:b074592e-44fe-4a6d-9bca-f8b7bd13ee69:card_description', 'rollback of teaser-card-s025: card_description ''The Colossi of Memnon are two large stone statues of the Pharaoh Amenhotep III, which stand at the front of the ruined Mortuary Temple of Amenhotep III.'' restored on Colossi of Memnon', '3e0254674531180fa0b31defabd8018dbf9838e49acfc3f86baee50de729f1d6|1934b2d3cf7a21ce54b5fdbb39a88c3f2bb31f19da6233d7a5a63b4a330c5417|1934b2d3cf7a21ce54b5fdbb39a88c3f2bb31f19da6233d7a5a63b4a330c5417', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Two huge statues of Amenhotep III, the Colossi of Memnon have stood since 1350 BC. Of their 107 Roman-era inscriptions, many name Memnon, the mythical king one was wrongly thought to be."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Colossi of Memnon are two huge statues [S1, S4]; the statues depict Amenhotep III [S1]; they have stood since 1350 BC [S2]; the statues bear 107 Roman-era inscriptions [S3]; many of the inscriptions name Memnon [S3]; Memnon was a mythical king [S3]; one statue was wrongly thought to represent Memnon [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Colossi of Memnon are two huge statues [SUPPORTED: https://en.wikipedia.org/wiki/Colossi_of_Memnon]; The statues depict Amenhotep III [SUPPORTED: https://en.wikipedia.org/wiki/Colossi_of_Memnon]; They have stood since 1350 BC [SUPPORTED: https://en.wikipedia.org/wiki/Colossi_of_Memnon]; The statues bear 107 inscriptions [SUPPORTED: https://en.wikipedia.org/wiki/Colossi_of_Memnon]; The inscriptions are Roman-era [SUPPORTED: https://en.wikipedia.org/wiki/Colossi_of_Memnon]; Many inscriptions name Memnon [SUPPORTED: https://en.wikipedia.org/wiki/Colossi_of_Memnon]; Memnon is a mythical king [SUPPORTED: https://en.wikipedia.org/wiki/Colossi_of_Memnon]; One statue was wrongly thought to be Memnon [SUPPORTED: https://en.wikipedia.org/wiki/Colossi_of_Memnon]"}]'::jsonb),
    ('b0a89bee-ba85-4f69-a396-2d30707ff1e7'::uuid, 'card_description', 'On a sandy plain in Al Jawf stand the Columns of Rajajil, 54 groups of trimmed sandstone pillars. Their name comes from a word for men: from afar, it is said, they resemble a gathering.', NULL, 'teaser-card-s025-rollback:b0a89bee-ba85-4f69-a396-2d30707ff1e7:card_description', 'rollback of teaser-card-s025: card_description None restored on Columns of Rajajil', '3406c2f8ec83d7674ff6ed65ccf704d57201af9ab5e109782eaa00d2177bec23|e4ac366a16ef34175655a9cccdc9b3e8bac5d2ab822280a0abc49a9028df2bb8|e4ac366a16ef34175655a9cccdc9b3e8bac5d2ab822280a0abc49a9028df2bb8', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a sandy plain in Al Jawf stand the Columns of Rajajil, 54 groups of trimmed sandstone pillars. Their name comes from a word for men: from afar, it is said, they resemble a gathering."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Columns of Rajajil stand on a sandy plain [S2]; the site is in Al Jawf [S1]; the site comprises 54 groups of trimmed pillars [S2]; the pillars are sandstone [S1]; the name comes from a word meaning men [S3]; from a distance the columns are said to resemble a gathering [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Columns of Rajajil are an archaeological site of pillars [SUPPORTED: https://en.wikipedia.org/wiki/Columns_of_Rajajil]; The site is in Al Jawf (Saudi Arabia) [SUPPORTED: https://en.wikipedia.org/wiki/Columns_of_Rajajil]; The pillars are made of sandstone [SUPPORTED: https://en.wikipedia.org/wiki/Columns_of_Rajajil]; The site stands on a sandy plain [SUPPORTED: https://en.wikipedia.org/wiki/Columns_of_Rajajil]; There are 54 groups of pillars [SUPPORTED: https://en.wikipedia.org/wiki/Columns_of_Rajajil]; The pillars are trimmed [SUPPORTED: https://en.wikipedia.org/wiki/Columns_of_Rajajil]; The name comes from a word for men [SUPPORTED: https://en.wikipedia.org/wiki/Columns_of_Rajajil]; From afar the columns are said to resemble a gathering [SUPPORTED: https://en.wikipedia.org/wiki/Columns_of_Rajajil]"}]'::jsonb),
    ('b0fdd6ca-3571-4452-9e64-9689ceb1445b'::uuid, 'card_description', 'Inuit mythology sets the last battle with Nordic settlers at the foot of Pisissarfik. The graves below its cliff proved to be Inuit burials of the 16th to 17th century, naturally mummified.', 'A 1,220-metre mountain with Norse farmsteads at its base that were part of the Western Settlement until about 1350 AD. Conflicts with the Inuit and climate change ended them.', 'teaser-card-s025-rollback:b0fdd6ca-3571-4452-9e64-9689ceb1445b:card_description', 'rollback of teaser-card-s025: card_description ''A 1,220-metre mountain with Norse farmsteads at its base that were part of the Western Settlement until about 1350 AD. Conflicts with the Inuit and climate change ended them.'' restored on Pisissarfik', '8ba58a1687c00f01aa48a9a1bf9c9f9d981ca66785cc33019455fee18f83f4b1|e891057c7124a4c606bd599a2c6aa639860d5f235f98fe2363de95c70ff6f8e5|e891057c7124a4c606bd599a2c6aa639860d5f235f98fe2363de95c70ff6f8e5', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Inuit mythology sets the last battle with Nordic settlers at the foot of Pisissarfik. The graves below its cliff proved to be Inuit burials of the 16th to 17th century, naturally mummified."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Inuit mythology places the final battle with Nordic settlers at the foot of Pisissarfik [S4]; there are graves below the mountain''s cliff [S5]; the graves proved to be Inuit burials [S6]; the burials date from the 16th to 17th century [S6]; the bodies in the graves were naturally mummified [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pisissarfik is a mountain in Greenland with a cliff [SUPPORTED: https://en.wikipedia.org/wiki/Pisissarfik]; Inuit mythology sets the last battle with Nordic settlers at the foot of Pisissarfik [SUPPORTED: https://en.wikipedia.org/wiki/Pisissarfik]; The graves lie below the cliff [SUPPORTED: https://en.wikipedia.org/wiki/Pisissarfik]; The graves proved to be Inuit burials, not battle graves [SUPPORTED: https://en.wikipedia.org/wiki/Pisissarfik]; The burials date to the 16th to 17th century [SUPPORTED: https://en.wikipedia.org/wiki/Pisissarfik]; The bodies are naturally mummified [SUPPORTED: https://en.wikipedia.org/wiki/Pisissarfik]"}]'::jsonb),
    ('b1123dfd-4f7d-41eb-ac61-c3676182448d'::uuid, 'card_description', 'Almost 300 m long, the Alconétar Bridge carried the Roman Via de la Plata over the Tagus on flattened arches, one of the earliest of its kind. In 1970 its ruins were moved for a reservoir.', 'A Roman bridge with unusually flat segmental arches, among the earliest of their kind. Its span-to-rise ratio of 4-5:1 was an engineering leap beyond traditional semicircular designs.', 'teaser-card-s025-rollback:b1123dfd-4f7d-41eb-ac61-c3676182448d:card_description', 'rollback of teaser-card-s025: card_description ''A Roman bridge with unusually flat segmental arches, among the earliest of their kind. Its span-to-rise ratio of 4-5:1 was an engineering leap beyond traditional semicircular designs.'' restored on Alconétar Bridge', '9cc890b04a213203a5bf187c0ea9e968b5a3b42f075e8144acd143be3910adbd|f5f5162dd996886646a0e8e628086d80873029693662c14f76c108f510d889f5|f5f5162dd996886646a0e8e628086d80873029693662c14f76c108f510d889f5', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Almost 300 m long, the Alconétar Bridge carried the Roman Via de la Plata over the Tagus on flattened arches, one of the earliest of its kind. In 1970 its ruins were moved for a reservoir."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the bridge is almost 300 m long [S4]; the bridge carried the Roman Via de la Plata [S4]; the bridge crossed the Tagus [S4]; the bridge had flattened arches [S2]; it is one of the earliest of its kind [S2]; in 1970 its ruins were moved [S5]; the ruins were moved because of a reservoir [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Alconetar Bridge was a Roman bridge [SUPPORTED: https://en.wikipedia.org/wiki/Alcon%C3%A9tar_Bridge]; It was almost 300 m long [SUPPORTED: https://en.wikipedia.org/wiki/Alcon%C3%A9tar_Bridge]; It carried the Roman Via de la Plata [SUPPORTED: https://en.wikipedia.org/wiki/Alcon%C3%A9tar_Bridge]; It crossed the Tagus [SUPPORTED: https://en.wikipedia.org/wiki/Alcon%C3%A9tar_Bridge]; It had flattened arches [SUPPORTED: https://en.wikipedia.org/wiki/Alcon%C3%A9tar_Bridge]; It is one of the earliest of its kind [SUPPORTED: https://en.wikipedia.org/wiki/Alcon%C3%A9tar_Bridge]; In 1970 its ruins were moved because of a reservoir [SUPPORTED: https://en.wikipedia.org/wiki/Alcon%C3%A9tar_Bridge]"}]'::jsonb),
    ('b202a257-17d5-4bc3-b983-496bc68dfd40'::uuid, 'card_description', 'At Delphi, the Lesche of the Knidians once held two famous paintings by Polygnotus, the Capture of Troy and the Nekyia. Of this meeting place, only some architectural relics survive.', '5th-century BC club and meeting hall at Delphi Sanctuary of Apollo. The Lesche of the Knidians housed two celebrated Polygnotus paintings, the Capture of Troy and the Nekyia, now lost with the hall.', 'teaser-card-s025-rollback:b202a257-17d5-4bc3-b983-496bc68dfd40:card_description', 'rollback of teaser-card-s025: card_description ''5th-century BC club and meeting hall at Delphi Sanctuary of Apollo. The Lesche of the Knidians housed two celebrated Polygnotus paintings, the Capture of Troy and the Nekyia, now lost with the hall.'' restored on Lesche of the Knidians', '94f34a59e472d056661bc3cd58c99b847b89e8454bde3d53f38c4898777974b3|5b8a3d696e3ecb67a67b3864bbd15b6a11d9779257fd19b42edab8ef90e6e3e6|5b8a3d696e3ecb67a67b3864bbd15b6a11d9779257fd19b42edab8ef90e6e3e6', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "At Delphi, the Lesche of the Knidians once held two famous paintings by Polygnotus, the Capture of Troy and the Nekyia. Of this meeting place, only some architectural relics survive."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Lesche of the Knidians is at Delphi [S1]; it once held two famous paintings by Polygnotus [S3]; the paintings were the Capture of Troy and the Nekyia [S3]; it was a meeting place [S1]; only some architectural relics survive [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOME