    ('d9ad0ebd-039e-4cc6-990a-41f690e94795'::uuid, 'card_description', 'By Jerusalem''s Jaffa Gate rises the Tower of David. Herod added massive towers here in 37–34 BCE; in 1310 a Mamluk sultan rebuilt the citadel, giving it much of its present shape.', 'A citadel rebuilt by every empire that held the city -- Hasmonean, Herodian, Byzantine, Crusader, Mamluk, and Ottoman. Its quarry dates to the First Temple period.', 'teaser-card-s025-rollback:d9ad0ebd-039e-4cc6-990a-41f690e94795:card_description', 'rollback of teaser-card-s025: card_description ''A citadel rebuilt by every empire that held the city -- Hasmonean, Herodian, Byzantine, Crusader, Mamluk, and Ottoman. Its quarry dates to the First Temple period.'' restored on Tower of David', 'e8a865f519b239ed87f75a1bfb0a1658e7c35d970d467848ce5175aabb19d71b|42773cf9c24c4e2da876d5294aed6a6e71b789835c38bee8b5eed2529c9d503a|42773cf9c24c4e2da876d5294aed6a6e71b789835c38bee8b5eed2529c9d503a', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "By Jerusalem''s Jaffa Gate rises the Tower of David. Herod added massive towers here in 37–34 BCE; in 1310 a Mamluk sultan rebuilt the citadel, giving it much of its present shape."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Tower of David stands by Jerusalem''s Jaffa Gate [S1]; Herod added massive towers at this spot [S4, S5]; Herod''s towers date to 37-34 BCE [S4]; in 1310 a Mamluk sultan rebuilt the citadel [S6]; that rebuilding gave the citadel much of its present shape [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Tower of David is a citadel in Jerusalem (Old City) [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_David]; It stands by Jaffa Gate [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_David]; Herod added massive towers to the fortifications here [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_David]; Herod''s towers were added in 37-34 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_David]; In 1310 a Mamluk sultan rebuilt the citadel [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_David]; The 1310 rebuilding gave the citadel much of its present shape [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_David]"}]'::jsonb),
    ('da488c94-540b-4fdc-8d3a-0d5aba57b372'::uuid, 'card_description', 'Refugees from Samos founded Pozzuoli in 531 BC. As Puteoli, its fortified harbor withstood the advances of Hannibal and grew into the primary commercial port of Rome.', 'A Greek colony founded around 531 BC by refugees fleeing the tyranny of Polycrates on Samos. It became a major Roman port and commercial center.', 'teaser-card-s025-rollback:da488c94-540b-4fdc-8d3a-0d5aba57b372:card_description', 'rollback of teaser-card-s025: card_description ''A Greek colony founded around 531 BC by refugees fleeing the tyranny of Polycrates on Samos. It became a major Roman port and commercial center.'' restored on Pozzuoli', '57a90b8e9c82fba04c661b1808fd504ae937993e756ac9c0d24bcfaca2bbfe4a|c8abc7514b598311e69845cedd34db6850ca3047ed132ccad8cd6b8c36f9bb08|c8abc7514b598311e69845cedd34db6850ca3047ed132ccad8cd6b8c36f9bb08', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Refugees from Samos founded Pozzuoli in 531 BC. As Puteoli, its fortified harbor withstood the advances of Hannibal and grew into the primary commercial port of Rome."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pozzuoli was founded by refugees from Samos [S1]; it was founded in 531 BC [S1]; the city was known as Puteoli [S1]; its fortified harbor withstood the advances of Hannibal [S2]; it became the primary commercial port of Rome [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pozzuoli is a city/settlement (ancient Puteoli, a port city) in Italy [SUPPORTED: https://en.wikipedia.org/wiki/Pozzuoli]; It was founded by refugees from Samos [SUPPORTED: https://en.wikipedia.org/wiki/Pozzuoli]; It was founded in 531 BC [SUPPORTED: https://en.wikipedia.org/wiki/Pozzuoli]; Its ancient name was Puteoli [SUPPORTED: https://en.wikipedia.org/wiki/Pozzuoli]; Its harbor was fortified [SUPPORTED: https://en.wikipedia.org/wiki/Pozzuoli]; Its fortified harbor withstood the advances of Hannibal [SUPPORTED: https://en.wikipedia.org/wiki/Pozzuoli]; It grew into the primary commercial port of Rome [SUPPORTED: https://en.wikipedia.org/wiki/Pozzuoli]"}]'::jsonb),
    ('dc38ed07-f75e-4d92-b932-cd8275b35a09'::uuid, 'card_description', 'On a high plateau behind the Devon coast, the complex earthworks of Clovelly Dykes cover more than 20 acres: one of the largest Early Iron Age hill-forts in Devon.', 'An excavation was carried out at Clovelly Dykes in about 1903, but it is poorly documented.', 'teaser-card-s025-rollback:dc38ed07-f75e-4d92-b932-cd8275b35a09:card_description', 'rollback of teaser-card-s025: card_description ''An excavation was carried out at Clovelly Dykes in about 1903, but it is poorly documented.'' restored on Clovelly Dykes', '01cf507b7ffd51ad3e6b800a300d87cad92653d068d184f130dcef0f56e39d8c|3c700600330fb9940124ed3dc78ba64b5f9f49de8c630d1448fbb8aa2859b733|3c700600330fb9940124ed3dc78ba64b5f9f49de8c630d1448fbb8aa2859b733', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a high plateau behind the Devon coast, the complex earthworks of Clovelly Dykes cover more than 20 acres: one of the largest Early Iron Age hill-forts in Devon."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Clovelly Dykes lies on a high plateau behind the coast [S2]; it is in Devon [S1]; it is a complex of earthworks [S3]; the earthworks cover more than 20 acres [S3]; it is one of the largest Early Iron Age hill-forts in Devon [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Clovelly Dykes is an Iron Age hill-fort/earthwork [SUPPORTED: https://en.wikipedia.org/wiki/Clovelly_Dykes]; It lies in Devon, England [SUPPORTED: https://en.wikipedia.org/wiki/Clovelly_Dykes]; It sits on a high plateau behind the coast [SUPPORTED: https://en.wikipedia.org/wiki/Clovelly_Dykes]; It is one of the largest hill-forts in Devon [SUPPORTED: https://en.wikipedia.org/wiki/Clovelly_Dykes]; It is an Early Iron Age hill-fort [SUPPORTED: https://en.wikipedia.org/wiki/Clovelly_Dykes]; Its earthworks are a complex series [SUPPORTED: https://en.wikipedia.org/wiki/Clovelly_Dykes]; The earthworks cover more than 20 acres [SUPPORTED: https://en.wikipedia.org/wiki/Clovelly_Dykes]"}]'::jsonb),
    ('dcb2b187-5d69-4824-bb7a-d098ba39231c'::uuid, 'card_description', 'About 3.2 miles west of Luccombe, a Somerset hillslope still holds the earthworks of Berry Castle, an enclosure from the late Iron Age or the early Romano British period.', 'Late Iron Age or early Roman hillslope enclosure in Somerset, protected as a scheduled monument. Multiple surviving earthworks mark the outline of a community poised between two eras.', 'teaser-card-s025-rollback:dcb2b187-5d69-4824-bb7a-d098ba39231c:card_description', 'rollback of teaser-card-s025: card_description ''Late Iron Age or early Roman hillslope enclosure in Somerset, protected as a scheduled monument. Multiple surviving earthworks mark the outline of a community poised between two eras.'' restored on Berry Castle, Somerset', '8a0b24f734e87e114e36bdb1996361b0af0d3e290a67ed189b86122f1391a99e|35aae4528630e237d7b1dd27409382da9f32ca5e2250702ae1218bf5f943bd95|35aae4528630e237d7b1dd27409382da9f32ca5e2250702ae1218bf5f943bd95', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "About 3.2 miles west of Luccombe, a Somerset hillslope still holds the earthworks of Berry Castle, an enclosure from the late Iron Age or the early Romano British period."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Berry Castle lies about 3.2 miles west of Luccombe [S2]; it is in Somerset [S1]; it is on a hillslope [S1]; earthworks of it survive [S3]; it is an enclosure [S1]; it dates from the late Iron Age or the early Romano British period [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Berry Castle is a hillslope enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Castle,_Somerset]; It is in Somerset, England [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Castle,_Somerset]; It lies about 3.2 miles west of Luccombe [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Castle,_Somerset]; Earthworks still survive there [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Castle,_Somerset]; It dates from the late Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Castle,_Somerset]; or from the early Romano-British period [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Castle,_Somerset]; It is a hill fort type enclosure on a hillslope [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Castle,_Somerset]"}]'::jsonb),
    ('dd425ddf-0128-45e2-84dd-c442978149e3'::uuid, 'card_description', 'Where the Jataka tales say Prince Sattva, an incarnation of the Buddha, sacrificed himself to feed seven hungry tiger cubs, rises the Manikyala Stupa, its mound torn by plunderers.', 'Mankiala stupa''s relic deposits were discovered by Jean-Baptiste Ventura in 1830.', 'teaser-card-s025-rollback:dd425ddf-0128-45e2-84dd-c442978149e3:card_description', 'rollback of teaser-card-s025: card_description "Mankiala stupa''s relic deposits were discovered by Jean-Baptiste Ventura in 1830." restored on Manikyala Stupa', '564490c3bbb81dab3e395b4b99b6b376a699b91041332bce0d426f7fde948736|35ae1649da86ebde428ddecedf05ee7ccaac925825c55ee3525e5c3bd643d335|35ae1649da86ebde428ddecedf05ee7ccaac925825c55ee3525e5c3bd643d335', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Where the Jataka tales say Prince Sattva, an incarnation of the Buddha, sacrificed himself to feed seven hungry tiger cubs, rises the Manikyala Stupa, its mound torn by plunderers."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Manikyala Stupa stands at the spot where, according to the Jataka tales, Prince Sattva sacrificed himself [S2]; Prince Sattva was an incarnation of the Buddha [S2]; he sacrificed himself to feed seven hungry tiger cubs [S2]; the stupa''s mound has been damaged by plunderers [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Manikyala Stupa is a Buddhist stupa [SUPPORTED: https://en.wikipedia.org/wiki/Manikyala_Stupa]; It is in Pakistan (Punjab) [SUPPORTED: https://en.wikipedia.org/wiki/Manikyala_Stupa]; According to the Jataka tales Prince Sattva sacrificed himself at the spot [SUPPORTED: https://en.wikipedia.org/wiki/Manikyala_Stupa]; Prince Sattva is an incarnation of the Buddha [SUPPORTED: https://en.wikipedia.org/wiki/Manikyala_Stupa]; He sacrificed himself to feed seven hungry tiger cubs [SUPPORTED: https://en.wikipedia.org/wiki/Manikyala_Stupa]; The stupa''s mound has a large defect made by plunderers [SUPPORTED: https://en.wikipedia.org/wiki/Manikyala_Stupa]"}]'::jsonb),
    ('de42523e-9322-4dba-9448-016174872c48'::uuid, 'card_description', 'The Pyramid of the Sun and the Pyramid of the Moon rise at Teotihuacan, a city of vibrant murals and the Avenue of the Dead, whose fine obsidian tools were found throughout Mesoamerica.', 'At its peak a city of 100,000 with an Avenue of the Dead flanked by pyramids, Teotihuacan dominated Mesoamerica from 600 BC to 750 AD. The Pyramid of the Sun stands 65 m tall and covers 4.5 hectares.', 'teaser-card-s025-rollback:de42523e-9322-4dba-9448-016174872c48:card_description', 'rollback of teaser-card-s025: card_description ''At its peak a city of 100,000 with an Avenue of the Dead flanked by pyramids, Teotihuacan dominated Mesoamerica from 600 BC to 750 AD. The Pyramid of the Sun stands 65 m tall and covers 4.5 hectares.'' restored on Teotihuacan', '2db9ef6d3cb7c2c598575b6cd89790de0e8c407209d18111e2b49984819fb836|1806961b0870fe269efe414b591994b8ec3884376757415a4e0d256546a3cd7e|1806961b0870fe269efe414b591994b8ec3884376757415a4e0d256546a3cd7e', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Pyramid of the Sun and the Pyramid of the Moon rise at Teotihuacan, a city of vibrant murals and the Avenue of the Dead, whose fine obsidian tools were found throughout Mesoamerica."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Pyramid of the Sun stands at Teotihuacan [S2]; the Pyramid of the Moon stands at Teotihuacan [S2]; Teotihuacan is a city [S1]; it has vibrant murals [S3]; it has the Avenue of the Dead [S3]; its fine obsidian tools were found throughout Mesoamerica [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Teotihuacan is a city in Mexico (close to Mexico City) [SUPPORTED: https://en.wikipedia.org/wiki/Teotihuacan]; It was a city, the largest in the Americas at its zenith [SUPPORTED: https://en.wikipedia.org/wiki/Teotihuacan]; The Pyramid of the Sun is at Teotihuacan [SUPPORTED: https://en.wikipedia.org/wiki/Teotihuacan]; The Pyramid of the Moon is at Teotihuacan [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Teotihuacan]; The city has vibrant murals [SUPPORTED: https://en.wikipedia.org/wiki/Teotihuacan]; The city has the Avenue of the Dead [SUPPORTED: https://en.wikipedia.org/wiki/Teotihuacan]; Teotihuacan exported fine obsidian tools [SUPPORTED: https://en.wikipedia.org/wiki/Teotihuacan]; The obsidian tools were found throughout Mesoamerica [SUPPORTED: https://en.wikipedia.org/wiki/Teotihuacan]"}]'::jsonb),
    ('de449341-fecc-48c2-ab1d-0087ce60e174'::uuid, 'card_description', 'Five Neolithic barrows lie on a limestone plateau in a loop of the river Bougon. At the Tumulus of Bougon, a drystone wall 35m long divides the site, unparalleled among French megaliths.', 'A group of five Neolithic barrows with structures dating to 4800 BC. The 1,000-year evolution of burial architecture here spans round mounds, long mounds, and stone chambers.', 'teaser-card-s025-rollback:de449341-fecc-48c2-ab1d-0087ce60e174:card_description', 'rollback of teaser-card-s025: card_description ''A group of five Neolithic barrows with structures dating to 4800 BC. The 1,000-year evolution of burial architecture here spans round mounds, long mounds, and stone chambers.'' restored on Tumulus of Bougon', '327fdc2ee7de7209ee6a106d18dfed54f5a2e4ca54c136a494e63bf5369afd98|03cce23c3ea589731aa68adb13d6a643ba5a158d8eeee239d1de6cd273c2089f|03cce23c3ea589731aa68adb13d6a643ba5a158d8eeee239d1de6cd273c2089f', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Five Neolithic barrows lie on a limestone plateau in a loop of the river Bougon. At the Tumulus of Bougon, a drystone wall 35m long divides the site, unparalleled among French megaliths."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site is a group of five barrows [S1]; the barrows are Neolithic [S1]; they lie on a limestone plateau [S5]; the plateau is in a loop of the river Bougon [S5]; a drystone wall divides the site [S7]; the wall is 35 m long [S7]; the wall is unparalleled among the megalithic monuments of France [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Tumulus of Bougon is a group of barrows (burial mounds) in France [SUPPORTED: https://en.wikipedia.org/wiki/Tumulus_of_Bougon]; There are five barrows [SUPPORTED: https://en.wikipedia.org/wiki/Tumulus_of_Bougon]; The barrows are Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Tumulus_of_Bougon]; The site is on a limestone plateau [SUPPORTED: https://en.wikipedia.org/wiki/Tumulus_of_Bougon]; The plateau lies within a loop of the river Bougon [SUPPORTED: https://en.wikipedia.org/wiki/Tumulus_of_Bougon]; A drystone wall 35 m long exists at the site [SUPPORTED: https://en.wikipedia.org/wiki/Tumulus_of_Bougon]; The wall divides the site [SUPPORTED: https://en.wikipedia.org/wiki/Tumulus_of_Bougon]; The wall is unparalleled among French megalithic monuments [SUPPORTED: https://en.wikipedia.org/wiki/Tumulus_of_Bougon]"}]'::jsonb),
    ('de912183-ceb0-4f02-835c-191dcbaeaec7'::uuid, 'card_description', 'At Sitio Arqueológico El Chal, a Maya site of the Petén, the acropolis crowns a 30-metre limestone hill, and six stelae and three altars were found in the East Plaza.', 'El Chal was occupied from approximately 300 BC through to 1300 AD, although some Middle Preclassic activity has been identified in the acropolis.', 'teaser-card-s025-rollback:de912183-ceb0-4f02-835c-191dcbaeaec7:card_description', 'rollback of teaser-card-s025: card_description ''El Chal was occupied from approximately 300 BC through to 1300 AD, although some Middle Preclassic activity has been identified in the acropolis.'' restored on Sitio Arqueológico El Chal', '8742a5744bf5dbe9455715cfd7f5bbbf6bbcce702fb7a323e84589c3b9b89b1a|4c0352894c4aa6accdb40bf6585c09df07b532549996538219c53c1c63c034c8|4c0352894c4aa6accdb40bf6585c09df07b532549996538219c53c1c63c034c8', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "At Sitio Arqueológico El Chal, a Maya site of the Petén, the acropolis crowns a 30-metre limestone hill, and six stelae and three altars were found in the East Plaza."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "El Chal is a Maya site [S1]; it is in the Petén [S1]; the acropolis sits on top of a limestone hill [S6]; the hill is 30 metres high [S6]; six stelae were found in the East Plaza [S7]; three altars were found in the East Plaza [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "El Chal is a Maya archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/El_Chal]; The site lies in the Peten of Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/El_Chal]; The site has an acropolis [SUPPORTED: https://en.wikipedia.org/wiki/El_Chal]; The acropolis stands on a limestone hill [SUPPORTED: https://en.wikipedia.org/wiki/El_Chal]; The hill is 30 metres high [SUPPORTED: https://en.wikipedia.org/wiki/El_Chal]; Six stelae were found in the East Plaza [SUPPORTED: https://en.wikipedia.org/wiki/El_Chal]; Three altars were found in the East Plaza [SUPPORTED: https://en.wikipedia.org/wiki/El_Chal]; The stelae and altars were found in the East Plaza (location) [SUPPORTED: https://en.wikipedia.org/wiki/El_Chal]"}]'::jsonb),
    ('df850648-a8ae-40c9-9b63-e1545d6746f2'::uuid, 'card_description', 'Three concentric stone walls ringed Los Millares near Almería, the outer with 19 bastions and a guarded gate. Inside lay simple dwellings and a large building with traces of copper smelting.', 'Radiocarbon dating has established that one wall collapsed and was rebuilt around 3025 BC.', 'teaser-card-s025-rollback:df850648-a8ae-40c9-9b63-e1545d6746f2:card_description', 'rollback of teaser-card-s025: card_description ''Radiocarbon dating has established that one wall collapsed and was rebuilt around 3025 BC.'' restored on Los Millares', 'e2e955b670e081bdab974c4e88918e8862520aad009d7a13afc44e6f87377337|31d84c26cbf72cb8371c88d2e33877380fa994c4282838f14d0b50db96885db4|31d84c26cbf72cb8371c88d2e33877380fa994c4282838f14d0b50db96885db4', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Three concentric stone walls ringed Los Millares near Almería, the outer with 19 bastions and a guarded gate. Inside lay simple dwellings and a large building with traces of copper smelting."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Los Millares was ringed by three concentric stone walls [S6]; it lies near Almería [S1]; the outer wall had 19 bastions [S6]; the outer wall had a guarded gate [S6]; simple dwellings lay inside the walls [S8]; a large building inside held evidence of copper smelting [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Los Millares is a Chalcolithic settlement (occupation site) [SUPPORTED: https://en.wikipedia.org/wiki/Los_Millares]; Los Millares lies near Almeria [SUPPORTED: https://en.wikipedia.org/wiki/Los_Millares]; Three concentric stone walls surrounded the site [SUPPORTED: https://en.wikipedia.org/wiki/Los_Millares]; The outer wall had 19 bastions [SUPPORTED: https://en.wikipedia.org/wiki/Los_Millares]; The outer wall had a gate that was guarded [SUPPORTED: https://en.wikipedia.org/wiki/Los_Millares]; Inside the walls lay simple dwellings [SUPPORTED: https://en.wikipedia.org/wiki/Los_Millares]; Inside the walls was one large building [SUPPORTED: https://en.wikipedia.org/wiki/Los_Millares]; The large building had traces of copper smelting [SUPPORTED: https://en.wikipedia.org/wiki/Los_Millares]"}]'::jsonb),
    ('dfb2dbf1-38da-4bbc-834e-d956c3a8a8d7'::uuid, 'card_description', 'Cumbemayo, the Narrow River, lies at 3,500 meters. Its Sanctuary is a huge cliff resembling a man''s head, and in the grotto of its mouth lie undecipherable petroglyphs.', 'Aqueducts, a grotto, and petroglyphs at 3,500 meters, built around 1500 BC. Stone-carved water channels redirected mountain streams with precision engineering.', 'teaser-card-s025-rollback:dfb2dbf1-38da-4bbc-834e-d956c3a8a8d7:card_description', 'rollback of teaser-card-s025: card_description ''Aqueducts, a grotto, and petroglyphs at 3,500 meters, built around 1500 BC. Stone-carved water channels redirected mountain streams with precision engineering.'' restored on Cumbemayo', '85edf4ff71e29edd2d1a05a83b9ad9f8e4aaeef5cd6142a18aa9bcb9f2cdd054|cb8a691d7145094d1f1e2830772a7fcd6e680bcb38560c1ad4a6cbbbf188ef26|cb8a691d7145094d1f1e2830772a7fcd6e680bcb38560c1ad4a6cbbbf188ef26', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Cumbemayo, the Narrow River, lies at 3,500 meters. Its Sanctuary is a huge cliff resembling a man''s head, and in the grotto of its mouth lie undecipherable petroglyphs."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the name Cumbemayo means Narrow River [S3]; it lies at 3,500 meters of elevation [S1]; its Sanctuary is a huge cliff [S4]; the cliff resembles a man''s head [S4]; the mouth of the head is a grotto [S4]; petroglyphs were found in the grotto [S4]; the petroglyphs are undecipherable [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Cumbemayo is an archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Cumbemayo]; Cumbemayo lies at 3,500 meters [SUPPORTED: https://en.wikipedia.org/wiki/Cumbemayo]; Cumbemayo means Narrow River [SUPPORTED: https://en.wikipedia.org/wiki/Cumbemayo]; It has a Sanctuary [SUPPORTED: https://en.wikipedia.org/wiki/Cumbemayo]; The Sanctuary is a huge cliff resembling a man''s head [SUPPORTED: https://en.wikipedia.org/wiki/Cumbemayo]; The mouth of the head is a grotto [SUPPORTED: https://en.wikipedia.org/wiki/Cumbemayo]; Petroglyphs lie in the grotto [SUPPORTED: https://en.wikipedia.org/wiki/Cumbemayo]; The petroglyphs are undecipherable [SUPPORTED: https://en.wikipedia.org/wiki/Cumbemayo]"}]'::jsonb),
    ('e0e45b1f-a762-481b-a278-cfa82c003518'::uuid, 'card_description', 'Scattered quartz may once have formed a wall at the entrances of Knockroe Passage Tomb, a Neolithic tomb in County Kilkenny known locally as The Caiseal, akin to Newgrange and Knowth.', 'A passage tomb aligned so that winter solstice sunset shines along the passageway. Scattered quartz may have once formed a gleaming white facade.', 'teaser-card-s025-rollback:e0e45b1f-a762-481b-a278-cfa82c003518:card_description', 'rollback of teaser-card-s025: card_description ''A passage tomb aligned so that winter solstice sunset shines along the passageway. Scattered quartz may have once formed a gleaming white facade.'' restored on Knockroe Passage Tomb', 'e12d48beb773c88ad033997a25011f7517ed33d3f4183d35fbb2ba03c6b78a35|432bf802d0881fc77637952a62b75b9b43845b8f3caf20100acd5c343ba1e31b|432bf802d0881fc77637952a62b75b9b43845b8f3caf20100acd5c343ba1e31b', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Scattered quartz may once have formed a wall at the entrances of Knockroe Passage Tomb, a Neolithic tomb in County Kilkenny known locally as The Caiseal, akin to Newgrange and Knowth."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "quartz is scattered at the site [S3]; the quartz may once have formed a wall at the entrances [S3]; Knockroe Passage Tomb is Neolithic [S1]; it is in County Kilkenny [S1]; it is known locally as The Caiseal [S2]; it is similar to the tombs at Newgrange and Knowth [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Knockroe Passage Tomb is a tomb (a passage tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Knockroe_Passage_Tomb]; It is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Knockroe_Passage_Tomb]; It lies in County Kilkenny [SUPPORTED: https://en.wikipedia.org/wiki/Knockroe_Passage_Tomb]; It is known locally as The Caiseal [SUPPORTED: https://en.wikipedia.org/wiki/Knockroe_Passage_Tomb]; Quartz is scattered around the site [SUPPORTED: https://en.wikipedia.org/wiki/Knockroe_Passage_Tomb]; The quartz may have formed a wall at the entrances [SUPPORTED: https://en.wikipedia.org/wiki/Knockroe_Passage_Tomb]; It is akin to Newgrange [SUPPORTED: https://en.wikipedia.org/wiki/Knockroe_Passage_Tomb]; It is akin to Knowth [SUPPORTED: https://en.wikipedia.org/wiki/Knockroe_Passage_Tomb]"}]'::jsonb),
    ('e0ffa4e7-7b44-473d-af17-99abdfbef90e'::uuid, 'card_description', 'Within Lugbury Long Barrow in Wiltshire lay four burial chambers, three holding twenty-six skeletons of adults and children. A leaning limestone capstone marks a false entrance.', 'George Scrope excavated the site from 1854 to 1855, and a report was written by John Thurnam.', 'teaser-card-s025-rollback:e0ffa4e7-7b44-473d-af17-99abdfbef90e:card_description', 'rollback of teaser-card-s025: card_description ''George Scrope excavated the site from 1854 to 1855, and a report was written by John Thurnam.'' restored on Lugbury Long Barrow', '8e3c7adbf421e3ef433008c84504bfd6a1c20e4145640f8b9c5f6113fd4dca4c|7cd312d5d73eef28b3615362020e7be7dab8c19d4e15fb52d01730333264ed76|7cd312d5d73eef28b3615362020e7be7dab8c19d4e15fb52d01730333264ed76', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Within Lugbury Long Barrow in Wiltshire lay four burial chambers, three holding twenty-six skeletons of adults and children. A leaning limestone capstone marks a false entrance."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Lugbury Long Barrow is in Wiltshire [S1]; four burial chambers were found in it [S8]; three of the chambers held skeletons [S8]; there were twenty-six skeletons in total [S8]; the skeletons were of adults and children [S8]; there is a leaning capstone [S6]; the capstone is limestone [S6]; the capstone belongs to a false entrance [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Lugbury Long Barrow is a long barrow (burial place) [SUPPORTED: https://en.wikipedia.org/wiki/Lugbury_Long_Barrow]; It lies in Wiltshire [SUPPORTED: https://en.wikipedia.org/wiki/Lugbury_Long_Barrow]; Four burial chambers were found [SUPPORTED: https://en.wikipedia.org/wiki/Lugbury_Long_Barrow]; Three of the chambers held skeletons [SUPPORTED: https://en.wikipedia.org/wiki/Lugbury_Long_Barrow]; The three chambers held twenty-six skeletons in total [SUPPORTED: https://en.wikipedia.org/wiki/Lugbury_Long_Barrow]; The skeletons were of adults and children [SUPPORTED: https://en.wikipedia.org/wiki/Lugbury_Long_Barrow]; A capstone leans against upright stones [SUPPORTED: https://en.wikipedia.org/wiki/Lugbury_Long_Barrow]; The capstone is limestone [SUPPORTED: https://en.wikipedia.org/wiki/Lugbury_Long_Barrow]; The capstone and stones formed a false entrance [SUPPORTED: https://en.wikipedia.org/wiki/Lugbury_Long_Barrow]"}]'::jsonb),
    ('e20a253e-63e2-4423-9852-c05615206f93'::uuid, 'card_description', 'In the Iron Gates gorge of the Danube, Lepenski Vir buried some of its dead under the house floors, and sandstone river cobbles became fish sculptures with human-like faces.', 'A Mesolithic settlement from 9500 BC with trapezoidal buildings and eerie fish-human stone sculptures. It may represent one of the first planned villages in European prehistory.', 'teaser-card-s025-rollback:e20a253e-63e2-4423-9852-c05615206f93:card_description', 'rollback of teaser-card-s025: card_description ''A Mesolithic settlement from 9500 BC with trapezoidal buildings and eerie fish-human stone sculptures. It may represent one of the first planned villages in European prehistory.'' restored on Lepenski Vir', '22d926b989b0ab4a8a703b6fd90f32e52f600c3b10b0ec285c30f155ed101bed|564dcd386babe38c06945604a0ffe6766f99e7d1427585f732bd2bd49e82a24f|564dcd386babe38c06945604a0ffe6766f99e7d1427585f732bd2bd49e82a24f', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In the Iron Gates gorge of the Danube, Lepenski Vir buried some of its dead under the house floors, and sandstone river cobbles became fish sculptures with human-like faces."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Lepenski Vir lies in the Iron Gates gorge [S3]; it is on the Danube [S3]; some of the dead were buried under the house floors [S6]; the sculptures were carved from sandstone cobbles from the river banks [S7]; the sculptures depict fish with human-like faces [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Lepenski Vir is a prehistoric settlement (Mesolithic/Neolithic) site [SUPPORTED: https://en.wikipedia.org/wiki/Lepenski_Vir]; It lies in the Iron Gates gorge of the Danube, in Serbia [SUPPORTED: https://en.wikipedia.org/wiki/Lepenski_Vir]; Some of its dead were buried under the house floors [SUPPORTED: https://en.wikipedia.org/wiki/Lepenski_Vir]; The sculptures were made from sandstone river cobbles [SUPPORTED: https://en.wikipedia.org/wiki/Lepenski_Vir]; The sculptures are fish sculptures with human-like faces [SUPPORTED: https://en.wikipedia.org/wiki/Lepenski_Vir]"}]'::jsonb),
    ('e21d32e0-beba-4e70-9a7f-2a56cf70a476'::uuid, 'card_description', 'Huaca Prieta, an Andean preceramic settlement on the Pacific in the Chicama Valley: its people fished, gathered shellfish and grew gourds, squash, beans and, importantly, cotton.', 'A mound of ash, stones, textiles, and shells with occupation from 12,500 BC. Some of the oldest known woven textiles in the Americas come from this site.', 'teaser-card-s025-rollback:e21d32e0-beba-4e70-9a7f-2a56cf70a476:card_description', 'rollback of teaser-card-s025: card_description ''A mound of ash, stones, textiles, and shells with occupation from 12,500 BC. Some of the oldest known woven textiles in the Americas come from this site.'' restored on Huaca Prieta', '9195af16b8210010a293dbf990df391725bc2f25335fcaf10c3cbc6a2ebc463e|2b1e6dda7793e51f13ab468090fb21e0593f8ae48131bab46f738cb56c199fed|2b1e6dda7793e51f13ab468090fb21e0593f8ae48131bab46f738cb56c199fed', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Huaca Prieta, an Andean preceramic settlement on the Pacific in the Chicama Valley: its people fished, gathered shellfish and grew gourds, squash, beans and, importantly, cotton."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Huaca Prieta is an Andean preceramic settlement [S1]; it lies on the Pacific in the Chicama Valley [S1]; its people fished [S3]; its people gathered shellfish [S3]; its people grew gourds, squash and beans [S3]; its people grew cotton, and cotton was important [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Huaca Prieta is a settlement (the central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Prieta]; It is Andean and preceramic [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Prieta]; It lies on the Pacific in the Chicama Valley [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Prieta]; Its people fished [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Prieta]; Its people gathered shellfish [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Prieta]; Its people grew gourds and squash [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Prieta]; Its people grew beans [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Prieta]; Its people grew cotton, importantly [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Prieta]"}]'::jsonb),
    ('e364d6eb-f92a-44d7-80b2-025092a81561'::uuid, 'card_description', NULL, 'The walls of the fort were built by the Mughal prince Murad Bakhsh in the 17th century.', 'teaser-card-s025-rollback:e364d6eb-f92a-44d7-80b2-025092a81561:card_description', 'rollback of teaser-card-s025: card_description ''The walls of the fort were built by the Mughal prince Murad Bakhsh in the 17th century.'' restored on Multan Fort', '||3f02e4902e82f3ed8803bc438458a6b79db6504c14e7ab46f740cc7e1bda5df6', '[{"source": "lane WB run wb-ws-2026-09-27-05: contradicted-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The web check could not prove: Multan Fort was a historic fort in Multan, Pakistan, on a hillock by the Ravi River; The web check contradicts: The Sun Temple stood until British forces destroyed it in 1849 (implied by the sentence) (https://en.wikipedia.org/wiki/Multan_Sun_Temple: \"before being purportedly obliterated by the Mughal Emperor Aurangzeb at some point after 1666\")"}]'::jsonb),
    ('e3a400b7-f8cd-4c4d-a2b0-b79ac18d2258'::uuid, 'card_description', 'In Yucatán, the modern town of Acanceh sits partly atop an ancient Maya city, where a step pyramid reveals distinctive carved masks and the Palace of the Stuccos holds elaborate friezes.', 'The "Palace of the Stuccos" is 50 meters wide, 6 meters high, and contains many elaborate friezes.', 'teaser-card-s025-rollback:e3a400b7-f8cd-4c4d-a2b0-b79ac18d2258:card_description', 'rollback of teaser-card-s025: card_description ''The "Palace of the Stuccos" is 50 meters wide, 6 meters high, and contains many elaborate friezes.'' restored on Acanceh', 'd56a7c44d34c8ba32a3c80f51660454d6331ad72151638097cfb15a81fe69b2e|f846ebd92c5ec26c476aa6f0b7cf5e5912c22e2982bdace5123496a6414b7c4a|f846ebd92c5ec26c476aa6f0b7cf5e5912c22e2982bdace5123496a6414b7c4a', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In Yucatán, the modern town of Acanceh sits partly atop an ancient Maya city, where a step pyramid reveals distinctive carved masks and the Palace of the Stuccos holds elaborate friezes."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Acanceh is in Yucatán [S1]; the modern town of Acanceh sits partly atop the ancient site [S2]; the ancient site was a Maya city [S1, S3]; there is a step pyramid [S4]; the pyramid shows distinctive carved masks [S5]; there is a Palace of the Stuccos [S6]; the Palace of the Stuccos contains elaborate friezes [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Acanceh is a town in Yucatan, Mexico, that sits partly atop an ancient Maya city [SUPPORTED: https://en.wikipedia.org/wiki/Acanceh]; Acanceh is in the Mexican state of Yucatan and is an ancient Maya archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Acanceh]; Acanceh was an ancient Maya city (pre-Columbian site) [SUPPORTED: https://en.wikipedia.org/wiki/Acanceh]; The ancient Maya city had a step pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Acanceh]; A step pyramid has distinctive carved masks [SUPPORTED: https://en.wikipedia.org/wiki/Acanceh]; Acanceh has a Palace of the Stuccos building [SUPPORTED: https://en.wikipedia.org/wiki/Acanceh]; The Palace of the Stuccos holds elaborate friezes [SUPPORTED: https://en.wikipedia.org/wiki/Acanceh]"}]'::jsonb),
    ('e500a4eb-0731-4902-8380-c5a19a9d2a2b'::uuid, 'card_description', 'Prideaux Castle, also called Prideaux Warren or Prideaux War-Ring, keeps its first and second circular ramparts quite distinct, overgrown with trees on the north and east.', 'Iron Age multivallate hill fort on a 133-metre conical hill in Cornwall. Two distinct circular ramparts are visible despite heavy tree cover -- a commanding stronghold above the Cornish landscape.', 'teaser-card-s025-rollback:e500a4eb-0731-4902-8380-c5a19a9d2a2b:card_description', 'rollback of teaser-card-s025: card_description ''Iron Age multivallate hill fort on a 133-metre conical hill in Cornwall. Two distinct circular ramparts are visible despite heavy tree cover -- a commanding stronghold above the Cornish landscape.'' restored on Prideaux Castle', 'da474d5be755c060b0b449cf8f8b5a7471f35b20e222aedffbd5ecf74bcb57d0|fcf194c8eade0d506463364bd3ae747f2dac1414334ff549abcf999d6da9b2bf|fcf194c8eade0d506463364bd3ae747f2dac1414334ff549abcf999d6da9b2bf', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Prideaux Castle, also called Prideaux Warren or Prideaux War-Ring, keeps its first and second circular ramparts quite distinct, overgrown with trees on the north and east."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Prideaux Castle is also called Prideaux Warren [S2]; it is also called Prideaux War-Ring [S2]; its first and second circular ramparts remain quite distinct [S3]; they are overgrown with trees on the north and east [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Prideaux Castle is a hillfort with circular ramparts (the central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Prideaux_Castle]; It is also called Prideaux Warren or Prideaux War-Ring [SUPPORTED: https://en.wikipedia.org/wiki/Prideaux_Castle]; Its first and second circular ramparts are quite distinct [SUPPORTED: https://en.wikipedia.org/wiki/Prideaux_Castle]; They are overgrown with trees on the north and east [SUPPORTED: https://en.wikipedia.org/wiki/Prideaux_Castle]"}]'::jsonb),
    ('e50d493f-6f6c-4c30-8cab-5e86077ef361'::uuid, 'card_description', 'Near the river Guadiela, Ercavica enters history in 179 BC with the campaign of Tiberius Gracchus. Its Roman city grew a regular street plan, a city wall and a monumental Forum.', 'The Roman city was developed from the 2nd century BC with regular street plan, a city wall and public and private buildings.', 'teaser-card-s025-rollback:e50d493f-6f6c-4c30-8cab-5e86077ef361:card_description', 'rollback of teaser-card-s025: card_description ''The Roman city was developed from the 2nd century BC with regular street plan, a city wall and public and private buildings.'' restored on Ercavica', 'ee61cbc6260b6172a43ece86828fde4e919d8c627221ff22b31422dcd29cb506|318014b08f9e7a83d26a09816af93fd49cd64ff9d2308153e9ca03f6e7473e03|318014b08f9e7a83d26a09816af93fd49cd64ff9d2308153e9ca03f6e7473e03', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Near the river Guadiela, Ercavica enters history in 179 BC with the campaign of Tiberius Gracchus. Its Roman city grew a regular street plan, a city wall and a monumental Forum."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Ercavica lies near the river Guadiela [S3]; Ercavica is first mentioned in 179 BC [S4]; the first mention is in connection with the campaign of Tiberius Gracchus [S4]; it was a Roman city [S1, S5]; the Roman city developed a regular street plan [S5]; the Roman city had a city wall [S5]; it had a Forum made up of monumental buildings [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Ercavica is a Roman city (archaeological site) in Spain [SUPPORTED: https://en.wikipedia.org/wiki/Ercavica]; It lies near the river Guadiela [SUPPORTED: https://en.wikipedia.org/wiki/Ercavica]; Ercavica is first mentioned in 179 BC [SUPPORTED: https://en.wikipedia.org/wiki/Ercavica]; The campaign of 179 BC was that of Tiberius Gracchus [SUPPORTED: https://en.wikipedia.org/wiki/Ercavica]; The Roman city had a city wall [SUPPORTED: https://en.wikipedia.org/wiki/Ercavica]; The Roman city had a regular street plan [SUPPORTED: https://en.wikipedia.org/wiki/Ercavica]; The city had a monumental Forum [SUPPORTED: https://en.wikipedia.org/wiki/Ercavica]"}]'::jsonb),
    ('e5e74a71-b666-42a3-917b-cec6e80c81ca'::uuid, 'card_description', 'In the Classical Agora of Athens stood the Altar of the Twelve Gods, a place of supplication and refuge and, from at least the 5th century BC, the zero point for distances to Athens.', 'An altar set up in the Athenian Agora in 522 BC as the city''s central milestone. All distances from Athens were measured from this single point.', 'teaser-card-s025-rollback:e5e74a71-b666-42a3-917b-cec6e80c81ca:card_description', 'rollback of teaser-card-s025: card_description "An altar set up in the Athenian Agora in 522 BC as the city''s central milestone. All distances from Athens were measured from this single point." restored on Altar of the Twelve Gods', '9f137458b1754f0d3e7f9ac0c35aa240dc86826419cdbb95c0e701ff40198fd2|b4dd91ae1ed6f68a7180c5d0d9ed7c51f83ff9cbfc274e0a226d1940003b6a4d|b4dd91ae1ed6f68a7180c5d0d9ed7c51f83ff9cbfc274e0a226d1940003b6a4d', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In the Classical Agora of Athens stood the Altar of the Twelve Gods, a place of supplication and refuge and, from at least the 5th century BC, the zero point for distances to Athens."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Altar of the Twelve Gods stood in the Classical Agora of Athens [S1]; it was a place of supplication and refuge [S5]; from at least the 5th century BC it was the zero point from which distances to Athens were calculated [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Altar of the Twelve Gods was an altar and sanctuary in the Classical Agora of Athens [SUPPORTED: https://en.wikipedia.org/wiki/Altar_of_the_Twelve_Gods]; The altar was a place of supplication and refuge [SUPPORTED: https://en.wikipedia.org/wiki/Altar_of_the_Twelve_Gods]; From at least the 5th century BC it was the zero point for distances to Athens [SUPPORTED: https://en.wikipedia.org/wiki/Altar_of_the_Twelve_Gods]"}]'::jsonb),
    ('e6ec727e-8e27-4885-b2bb-a9aadd8f17c9'::uuid, 'card_description', 'In 1996 a building site gave up bones and human skulls: Herxheim, a Neolithic ritual center and mass grave, estimated to hold the scattered remains of more than 1000 individuals.', 'A Neolithic ritual center from 5300 BC with scattered remains of over 1,000 people from distant communities. The bones show signs of systematic defleshing.', 'teaser-card-s025-rollback:e6ec727e-8e27-4885-b2bb-a9aadd8f17c9:card_description', 'rollback of teaser-card-s025: card_description ''A Neolithic ritual center from 5300 BC with scattered remains of over 1,000 people from distant communities. The bones show signs of systematic defleshing.'' restored on Herxheim - Archaeological Site', 'ab69d9631fc2d22ed0401b75fd003ce944ffdf57a1be197cece8f099d866022b|ca90256c9d67e8f245c55bc2268e3d9a10955bac077a863ab7f1e3340d988c59|ca90256c9d67e8f245c55bc2268e3d9a10955bac077a863ab7f1e3340d988c59', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In 1996 a building site gave up bones and human skulls: Herxheim, a Neolithic ritual center and mass grave, estimated to hold the scattered remains of more than 1000 individuals."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site came to light in 1996 at a construction site [S3]; the finds included bones and human skulls [S3]; Herxheim is Neolithic [S1]; Herxheim was a ritual center [S1]; Herxheim was a mass grave [S1]; it is estimated to contain the scattered remains of more than 1000 individuals [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Herxheim was a Neolithic mass grave [SUPPORTED: https://en.wikipedia.org/wiki/Herxheim_(archaeological_site)]; Herxheim was a Neolithic ritual center [SUPPORTED: https://en.wikipedia.org/wiki/Herxheim_(archaeological_site)]; The site is in Germany [SUPPORTED: https://en.wikipedia.org/wiki/Herxheim_(archaeological_site)]; The site was discovered in 1996 [SUPPORTED: https://en.wikipedia.org/wiki/Herxheim_(archaeological_site)]; A building site gave up bones and human skulls [SUPPORTED: https://en.wikipedia.org/wiki/Herxheim_(archaeological_site)]; The site held the scattered remains of more than 1000 individuals [SUPPORTED: https://en.wikipedia.org/wiki/Herxheim_(archaeological_site)]; The figure of more than 1000 is an estimate [SUPPORTED: https://en.wikipedia.org/wiki/Herxheim_(archaeological_site)]"}]'::jsonb),
    ('e7b1d5cc-4481-4f5e-a1b6-d759ce1bd666'::uuid, 'card_description', 'On a coastal promontory by the Istron River, Priniatikos Pyrgos seems first settled circa 3000 BC, with activity spanning up to 4,000 years. Harbour, industrial area or cult place?', 'A coastal settlement first occupied around 3000 BC, active through the Minoan Bronze Age and into the Classical period. It sits on a promontory with views of the Cretan sea.', 'teaser-card-s025-rollback:e7b1d5cc-4481-4f5e-a1b6-d759ce1bd666:card_description', 'rollback of teaser-card-s025: card_description ''A coastal settlement first occupied around 3000 BC, active through the Minoan Bronze Age and into the Classical period. It sits on a promontory with views of the Cretan sea.'' restored on Priniatikos Pyrgos', '6c94fc2abd602c9dc8303af11c5652737f61c389f97e78c2d9db40403e89da50|dfa1120eeff9842d246b081ae5344e47b04465d5a8e9794a127fca6b8226e33f|dfa1120eeff9842d246b081ae5344e47b04465d5a8e9794a127fca6b8226e33f', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a coastal promontory by the Istron River, Priniatikos Pyrgos seems first settled circa 3000 BC, with activity spanning up to 4,000 years. Harbour, industrial area or cult place?"}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Priniatikos Pyrgos is on a coastal promontory [S2]; it lies near the Istron River [S1]; it appears to have been first settled circa 3000 BC (hedged) [S3]; activity at the site spans up to 4,000 years [S4]; the question implies the site''s function is uncertain: harbour, industrial area or cult place [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Priniatikos Pyrgos is an archaeological site by the Istron River (Crete, Greece) [SUPPORTED: https://en.wikipedia.org/wiki/Priniatikos_Pyrgos]; It lies on a coastal promontory [SUPPORTED: https://en.wikipedia.org/wiki/Priniatikos_Pyrgos]; It seems first settled circa 3000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Priniatikos_Pyrgos]; Activity spanned up to 4,000 years [SUPPORTED: https://en.wikipedia.org/wiki/Priniatikos_Pyrgos]; Its function (harbour, industrial area or cult place) is uncertain [SUPPORTED: https://en.wikipedia.org/wiki/Priniatikos_Pyrgos]"}]'::jsonb),
    ('e7bb01c3-14d8-4dd1-9e63-5d804927a032'::uuid, 'card_description', 'Marble ruins found in 1613 at Mtarfa: the Temple of Proserpina, goddess of the underworld. Its inscription says it was already old and near collapse when Chrestion restored it.', 'A Roman temple to Proserpina, goddess of the underworld. Its marble was later stripped and reused across Valletta—only one piece survives in place.', 'teaser-card-s025-rollback:e7bb01c3-14d8-4dd1-9e63-5d804927a032:card_description', 'rollback of teaser-card-s025: card_description ''A Roman temple to Proserpina, goddess of the underworld. Its marble was later stripped and reused across Valletta—only one piece survives in place.'' restored on Temple of Proserpina', '3817607244d4ccd93cd003003324fd34841c7b3ebce4c996850cb7de31b9a445|4ee275226e405f46081f47b1ab10f111ea09923616212ff8f828e422dc085780|4ee275226e405f46081f47b1ab10f111ea09923616212ff8f828e422dc085780', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Marble ruins found in 1613 at Mtarfa: the Temple of Proserpina, goddess of the underworld. Its inscription says it was already old and near collapse when Chrestion restored it."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the temple was built of marble [S8]; its ruins were discovered in 1613 [S4]; it is at Mtarfa [S1]; the Temple of Proserpina was dedicated to Proserpina [S2]; Proserpina is goddess of the underworld [S2]; an inscription of the temple records that it was already old [S5, S6]; the inscription records that it was threatening to collapse [S6]; Chrestion restored it [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Temple of Proserpina was a temple [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Proserpina]; The temple was built of marble [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Proserpina]; The temple stood at Mtarfa, Malta [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Proserpina]; It was dedicated to Proserpina, goddess of the underworld [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Proserpina]; Its marble ruins were found in 1613 [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Proserpina]; The inscription says the temple was already old [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Proserpina]; The inscription says the temple was near collapse [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Proserpina]; The temple was restored by Chrestion [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Proserpina]"}]'::jsonb),
    ('e7e09ce8-c980-405f-a877-ebb3c90dc7a2'::uuid, 'card_description', 'Unearthed only in 1998, the Tienen Mithraeum was a Mithraic temple of the third century CE. Ritual sites nearby held nearly 14,000 animal remains, mostly young pigs, sheep and chickens.', '3rd-century AD Mithraic temple, one of only four mithraea found here. Undiscovered until 1998, its ritual pit yielded feasting remains revealing the secret banqueting rites of the Mithraic cult.', 'teaser-card-s025-rollback:e7e09ce8-c980-405f-a877-ebb3c90dc7a2:card_description', 'rollback of teaser-card-s025: card_description ''3rd-century AD Mithraic temple, one of only four mithraea found here. Undiscovered until 1998, its ritual pit yielded feasting remains revealing the secret banqueting rites of the Mithraic cult.'' restored on Tienen Mithraeum', '08b30d1d3a0e7464f5b50b4bfe1f8cd97dd67444972e9ac9dfe14d3835336cd2|b9d820f7e2df7f8686480fd0aaa982392ed2fca167547bd20af933deabe57190|b9d820f7e2df7f8686480fd0aaa982392ed2fca167547bd20af933deabe57190', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Unearthed only in 1998, the Tienen Mithraeum was a Mithraic temple of the third century CE. Ritual sites nearby held nearly 14,000 animal remains, mostly young pigs, sheep and chickens."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Tienen Mithraeum was only discovered by excavation in 1998 [S2]; it was a Mithraic temple [S1]; it dates to the third century CE [S1]; ritual sites near it contained nearly 14,000 animal remains [S6]; most of the animals were pigs, sheep and chickens killed young [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Tienen Mithraeum is a Mithraic temple (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Tienen_Mithraeum]; It is in Tienen, Belgium [SUPPORTED: https://en.wikipedia.org/wiki/Tienen_Mithraeum]; The temple dates to the third century CE [SUPPORTED: https://en.wikipedia.org/wiki/Tienen_Mithraeum]; It was unearthed only in 1998 [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Tienen_Mithraeum]; Ritual sites near the mithraeum held nearly 14,000 animal remains [SUPPORTED: https://en.wikipedia.org/wiki/Tienen_Mithraeum]; The animals were mostly pigs, sheep and chickens [SUPPORTED: https://en.wikipedia.org/wiki/Tienen_Mithraeum]; The pigs, sheep and chickens were young (juvenile) [SUPPORTED: https://en.wikipedia.org/wiki/Tienen_Mithraeum]"}]'::jsonb),
    ('e8904b19-6c54-4560-8438-35ea9fbe8e8d'::uuid, 'card_description', 'Of the Hammerum Girl, buried in the late Roman Iron Age, only a complex coiffure survives, beside unusually well-preserved clothing, in a grave of the Hammerum Burial Site near Herning.', 'Roman Iron Age cemetery east of Herning, dated 200–400 AD. Grave 83 yielded only a preserved complex hairstyle — the elaborate coiffure of a young woman archaeologists named the Hammerum Girl.', 'teaser-card-s025-rollback:e8904b19-6c54-4560-8438-35ea9fbe8e8d:card_description', 'rollback of teaser-card-s025: card_description ''Roman Iron Age cemetery east of Herning, dated 200–400 AD. Grave 83 yielded only a preserved complex hairstyle — the elaborate coiffure of a young woman archaeologists named the Hammerum Girl.'' restored on Hammerum Burial Site', 'e6680227446cd1db035f8afc31b7dbd9fe4f0d6c7538f409f7d774a4281f1cd9|8e6e4cb0f7ce0f07a1e42d40aeee0adccf59ac7d1c11089ec1eb71268e69bdde|8e6e4cb0f7ce0f07a1e42d40aeee0adccf59ac7d1c11089ec1eb71268e69bdde', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Of the Hammerum Girl, buried in the late Roman Iron Age, only a complex coiffure survives, beside unusually well-preserved clothing, in a grave of the Hammerum Burial Site near Herning."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the grave''s occupant is called the Hammerum Girl [S6, S7]; she was buried in the late Roman Iron Age [S2]; the only surviving remains of the deceased are a complex coiffure [S6]; the grave contains unusually well-preserved clothing [S8]; the grave is part of the Hammerum Burial Site [S6, S7]; the site is near Herning [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Vinquoy Chambered Cairn is a chambered cairn (tomb) on Eday, Orkney, Scotland (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Vinquoy_chambered_cairn]; It stands on the highest point of Eday, above Calf Sound [SUPPORTED: https://en.wikipedia.org/wiki/Vinquoy_chambered_cairn]; It is built of red sandstone [SUPPORTED: https://en.wikipedia.org/wiki/Vinquoy_chambered_cairn]; It has a 5 m passage leading to a central chamber [SUPPORTED: https://en.wikipedia.org/wiki/Vinquoy_chambered_cairn]; The central chamber has four small side-cells [SUPPORTED: https://en.wikipedia.org/wiki/Vinquoy_chambered_cairn]; The cairn is carved into the hill [SUPPORTED: https://en.wikipedia.org/wiki/Vinquoy_chambered_cairn]"}]'::jsonb),
    ('e8f52f85-51d3-426c-8c5b-117fb9dfd6c3'::uuid, 'card_description', 'On the highest point of Eday, carved into the hill above Calf Sound, the red sandstone Vinquoy Chambered Cairn hides a 5 m passage to a central chamber with four small side-cells.', 'A restored Maeshowe-type Neolithic tomb on Eday island, built on the highest point with sweeping views. It dates to the early 3rd millennium BC.', 'teaser-card-s025-rollback:e8f52f85-51d3-426c-8c5b-117fb9dfd6c3:card_description', 'rollback of teaser-card-s025: card_description ''A restored Maeshowe-type Neolithic tomb on Eday island, built on the highest point with sweeping views. It dates to the early 3rd millennium BC.'' restored on Vinquoy Chambered Cairn', 'df9113824cfc288a26bb972aa37c339b140796da7c2e39902ff07baebb7f6c2f|1f42771bf1804b4a0591d2e57b9cf9719e35c138291d7e160a2193eba85a1247|1f42771bf1804b4a0591d2e57b9cf9719e35c138291d7e160a2193eba85a1247', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the highest point of Eday, carved into the hill above Calf Sound, the red sandstone Vinquoy Chambered Cairn hides a 5 m passage to a central chamber with four small side-cells."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the cairn is on the highest point of Eday [S3]; it is carved into the hill [S6]; it overlooks Calf Sound [S3]; it is built of red sandstone [S4]; it has a 5 m entrance passage [S5]; the passage leads to a central chamber [S5]; the central chamber has four small side-cells [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Valley of the Temples is an archaeological site at Agrigento (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Valle_dei_Templi]; The site is in Italy (Agrigento, Sicily) [SUPPORTED: https://en.wikipedia.org/wiki/Valle_dei_Templi]; It is not a valley (the name is a misnomer) [SUPPORTED: https://en.wikipedia.org/wiki/Valle_dei_Templi]; It is in fact a ridge [SUPPORTED: https://en.wikipedia.org/wiki/Valle_dei_Templi]; The ridge lies outside Agrigento [SUPPORTED: https://en.wikipedia.org/wiki/Valle_dei_Templi]; It holds the remains of seven temples [SUPPORTED: https://en.wikipedia.org/wiki/Valle_dei_Templi]; The seven temples are Doric [SUPPORTED: https://en.wikipedia.org/wiki/Valle_dei_Templi]; The Temple of Concordia is among them [SUPPORTED: https://en.wikipedia.org/wiki/Valle_dei_Templi]; The Temple of Concordia was once clad in polychrome stucco [SUPPORTED: https://en.wikipedia.org/wiki/Valle_dei_Templi]"}]'::jsonb),
    ('e9731acc-69e0-4c54-80ed-73dc1c0751c5'::uuid, 'card_description', 'Not a valley but a ridge outside Agrigento: the Valley of the Temples holds the remains of seven Doric temples, among them the Temple of Concordia, once clad in polychrome stucco.', 'A ridge of seven Doric temples from the 5th century BC, among the finest Greek temples outside of Greece itself. The "valley" name is misleading -- they sit on high ground.', 'teaser-card-s025-rollback:e9731acc-69e0-4c54-80ed-73dc1c0751c5:card_description', 'rollback of teaser-card-s025: card_description ''A ridge of seven Doric temples from the 5th century BC, among the finest Greek temples outside of Greece itself. The "valley" name is misleading -- they sit on high ground.'' restored on Valley of the Temples', 'e3bcb450d49dd75c21f98b81b795c065486fc44b241d2b8a0157f549913bd7cc|0606a51bd54fafbc145d51f7710f1224c939275c7f846d50ecd8e48c0e2cd0b8|0606a51bd54fafbc145d51f7710f1224c939275c7f846d50ecd8e48c0e2cd0b8', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Not a valley but a ridge outside Agrigento: the Valley of the Temples holds the remains of seven Doric temples, among them the Temple of Concordia, once clad in polychrome stucco."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site is not a valley but a ridge [S3]; it lies outside Agrigento [S3]; the Valley of the Temples includes the remains of seven temples [S4]; the temples are Doric [S4]; the Temple of Concordia is among them [S5]; the Temple of Concordia was covered in polychrome stucco [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Hammerum Burial Site is an archaeological burial site (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Hammerum_burial_site]; It is near Herning (Denmark) [SUPPORTED: https://en.wikipedia.org/wiki/Hammerum_burial_site]; The Hammerum Girl has a grave at the site [SUPPORTED: https://en.wikipedia.org/wiki/Hammerum_burial_site]; She was buried in the late Roman Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Hammerum_burial_site]; Only a complex coiffure survives of the deceased [SUPPORTED: https://en.wikipedia.org/wiki/Hammerum_burial_site]; The grave contains unusually well-preserved clothing [SUPPORTED: https://en.wikipedia.org/wiki/Hammerum_burial_site]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s025-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s025-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s025-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s025-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s025-rollback' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
